function emptyData(){const d={schema:1,pins:['學生週誌','出席總覽','學生進度'],mathUnits:[],kistLessons:[],meta:{lastExport:''}};for(const m of Object.values(modules))d[m.key]=[];return d;}
function normalize(d){
 for(const m of Object.values(modules))if(!Array.isArray(d[m.key]))d[m.key]=[];
 if(!Array.isArray(d.pins))d.pins=[];if(!Array.isArray(d.mathUnits))d.mathUnits=[];if(!Array.isArray(d.kistLessons))d.kistLessons=[];if(!d.meta||typeof d.meta!=='object'||Array.isArray(d.meta))d.meta={lastExport:''};
 if(!d.meta.summerMode||typeof d.meta.summerMode!=='object'||Array.isArray(d.meta.summerMode))d.meta.summerMode={on:false,from:'',to:''};
 if(!Array.isArray(d.meta.holidayBlocked))d.meta.holidayBlocked=[];
 d.summer.forEach(r=>{if(!r)return;if(r.am===undefined&&r.status)r.am=r.status;if(r.pm===undefined)r.pm='';});
 d.attendance.forEach(r=>{if(!r)return;if(r.status==='出席')r.status='準時';if(!r.time&&r.note){const m=String(r.note).match(/(?:到班|離開)\s*(\d{1,2}:\d{2})/);if(m){r.time=m[1].padStart(5,'0');r.note=String(r.note).replace(m[0],'').replace(/^[\s　]+|[\s　]+$/g,'');}}});
 d.classes.forEach(c=>{if(!c||typeof c!=='object')return;if(c.gradeRule===undefined)c.gradeRule=true;if(!c.kind)c.kind=kindFromName(c.name);if(!c.mode)c.mode='差異化教學';if(!c.online)c.online=onlineFromName(c.name);});
 d.students.forEach(s=>{if(!s)return;if(!Array.isArray(s.classIds))s.classIds=[];s.grade=canonicalGrade(s.grade);});
 d.progress.forEach(p=>{if(!p||typeof p!=='object')return;if(!p.unit&&p.title)p.unit=p.title;if(!p.start&&p.date)p.start=p.date;if(!Array.isArray(p.tasks)){p.tasks=[];const lines=String(p.note||'').split('\n'),first=lines[0]||'';if(/^[✓○]/.test(first)){p.tasks=first.split('、').map(x=>x.trim()).filter(Boolean).map(x=>({id:uid(),text:x.replace(/^[✓○]\s*/,''),done:x.startsWith('✓')}));const rest=lines.slice(1),di=rest.findIndex(l=>/^目標日\s*\d{4}-\d{2}-\d{2}/.test(l));if(di>=0){if(!p.due)p.due=rest[di].match(/\d{4}-\d{2}-\d{2}/)[0];rest.splice(di,1);}p.note=rest.join('\n');}}});
 d.grades.forEach(g=>{if(g&&typeof g==='object'){gInfer(g);if(g.section==='檢測'&&(g.subject==='數學'||d.classes.find(c=>c.id===g.classId)?.kind==='數學')){g.section='數學檢測';g.subject='數學';}}});
 if((d.meta.holidayVer||0)<1){TW_HOLIDAYS.forEach(([dt,t])=>{if(!d.calendar.some(e=>e&&e.date===dt&&e.kind==='國定假日'))d.calendar.push({id:uid(),date:dt,end:'',title:t,kind:'國定假日',classId:'',note:'內建'});});d.meta.holidayVer=1;}
 d.events=d.events.filter(e=>{const m=e&&String(e.note||'').match(/^(?:(\d{4}-\d{2}-\d{2})～(\d{4}-\d{2}-\d{2})　)?(停課|補課)$/);if(!m)return true;if(!d.calendar.some(x=>x.date===e.date&&x.title===e.title&&(x.classId||'')===(e.classId||'')))d.calendar.push({id:uid(),date:e.date,end:m[2]||'',title:e.title,kind:m[3],classId:e.classId||'',note:''});return false;});
 d.journals.forEach(j=>{if(j&&typeof j==='object'){if(!Array.isArray(j.tasks))j.tasks=[];if(!Array.isArray(j.readings))j.readings=[];}});
 [...d.journals].filter(j=>j&&(String(j.note||'').trim()||String(j.next||'').trim())&&/^\d{4}-\d{2}-\d{2}$/.test(j.date||'')).sort((a,b)=>String(a.date).localeCompare(String(b.date))).forEach(j=>{const ws=weekStartOf(j.date);const subject=d.classes.find(c=>c.id===j.classId)?.kind||'未分類';let w=d.weeklyObs.find(x=>x&&x.studentId===j.studentId&&x.week===ws&&(x.subject||d.classes.find(c=>c.id===x.classId)?.kind||'未分類')===subject);if(!w){w={id:uid(),studentId:j.studentId,classId:j.classId||'',subject,week:ws,note:'',next:''};d.weeklyObs.push(w);}
  for(const k of ['note','next']){const v=String(j[k]||'').trim();if(v&&!String(w[k]||'').includes(v))w[k]=w[k]?w[k]+'\n'+v:v;j[k]='';}});
 applyAnnualGradePromotion(d);
 return d;}
function validateImport(d){
 if(!d||typeof d!=='object'||d.schema!==1)throw Error('這不是本系統的備份格式。');normalize(d);
 const prim=v=>v==null||['string','boolean','number'].includes(typeof v);
 for(const m of Object.values(modules)){const ids=new Set();for(const r of d[m.key]){
  if(!r||typeof r!=='object'||typeof r.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(r.id)||ids.has(r.id))throw Error('紀錄識別碼無效或重複（'+m.key+'）。');ids.add(r.id);
  for(const f of m.fields)if(f.type==='images'?!(r[f.key]==null||Array.isArray(r[f.key])&&r[f.key].every(x=>x&&typeof x==='object'&&Object.values(x).every(prim))):f.type==='classes'?!(r[f.key]==null||Array.isArray(r[f.key])&&r[f.key].every(x=>typeof x==='string')):!prim(r[f.key]))throw Error('欄位格式不正確（'+m.key+'）。');
  if(r.images!=null&&!(Array.isArray(r.images)&&r.images.every(x=>x&&typeof x==='object'&&Object.values(x).every(prim))))throw Error('圖片格式不正確（'+m.key+'）。');for(const k of ['tasks','readings'])if(r[k]!=null&&r[k].some(x=>!x||typeof x!=='object'||!Object.values(x).every(prim)))throw Error('週誌清單格式不正確。');}}
 if(d.pins.some(p=>typeof p!=='string')||d.mathUnits.some(p=>typeof p!=='string')||d.kistLessons.some(p=>typeof p!=='string'))throw Error('選單格式不正確。');
 return d;}
function loadData(){
 let raw=null;try{raw=localStorage.getItem(STORE);}catch(e){showBanner('瀏覽器不允許儲存資料（可能是無痕模式），關閉頁面後資料會消失。請記得匯出備份。');}
 if(raw){try{return validateImport(JSON.parse(raw));}catch(e){try{localStorage.setItem(STORE+'-damaged-'+Date.now(),raw);}catch{}showBanner('本機資料無法讀取，已另存一份損壞副本並以空白資料開始。可到「資料匯入匯出」匯入備份。');}}
 return emptyData();}
function persist(){const json=JSON.stringify(data),saveTime=()=>new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'});try{localStorage.setItem(STORE,json);try{localStorage.removeItem('sindy-local-cache-stale');}catch{}if(typeof bigClear==='function')bigClear();if(typeof cloudSchedule==='function')cloudSchedule();status('✓ 已儲存 · '+new Date().toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'}));return true;}catch(e){try{localStorage.setItem('sindy-local-cache-stale','1');}catch{}if(typeof bigSave==='function'&&bigSave(json)){if(typeof cloudSchedule==='function')cloudSchedule();status('✓ 已儲存 · '+saveTime()+'（大容量空間）');return true;}if(typeof cloudSchedule==='function'&&cloud.url){cloudSchedule();status('本機快取已滿 · 正在儲存到雲端');return false;}status('儲存失敗',true);showBanner('無法寫入瀏覽器儲存空間：'+esc(e.message)+'。請立即匯出 JSON 備份。');return false;}}
