const byNum=(a,b)=>String(a.number||'').localeCompare(String(b.number||''),'zh-Hant',{numeric:true})||String(a.name||'').localeCompare(String(b.name||''),'zh-Hant');
function classOrder(id){const i=data.classes.findIndex(c=>c.id===id);return i<0?999:i;}
