const weekday=d=>new Date(d+'T00:00:00').getDay();
function addDays(d,n){const x=new Date(d+'T00:00:00');x.setDate(x.getDate()+n);return fmt(x);}
function shiftMonth(m,n){const [y,mm]=m.split('-').map(Number);return fmt(new Date(y,mm-1+n,1)).slice(0,7);}
function monthDays(month){const [y,m]=month.split('-').map(Number);const out=[];for(const d=new Date(y,m-1,1);d.getMonth()===m-1;d.setDate(d.getDate()+1))if(d.getDay()>=1&&d.getDay()<=5)out.push(fmt(d));return out;}
function gradeNum(g){g=String(g||'');const cn={一:1,二:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9};let n=0;const d=g.match(/\d+/),c=g.match(/[一二三四五六七八九]/);if(d)n=+d[0];else if(c)n=cn[c[0]];if(/國中|國[一二三1-3]/.test(g)&&n>=1&&n<=3)n+=6;return n;}
// 排課規則：週一至週四 3–6 年級；週五 7–9 年級。未填年級者每天都列入。
function parseWeekdays(t){const out=[];for(const ch of String(t||'')){let i='日一二三四五六'.indexOf(ch);if(i<0&&/[1-7]/.test(ch))i=+ch%7;if(i>=0&&!out.includes(i))out.push(i);}return out;}
