function journalProgressAttended(j){const cls=recordClass(j),calendar=calFor(j.date,cls);if(calendar&&!calendar.open)return false;const attendance=(data.attendance||[]).find(a=>a.studentId===j.studentId&&a.date===j.date&&(!a.classId||a.classId===cls));return !attendance||['準時','出席','遲到','早退'].includes(attendance.status);}
