function lastSessionJournals(date){const prev=data.journals.filter(j=>recordClass(j)===jClass&&j.date<date&&hasJournalProgress(j)&&journalProgressAttended(j));if(!prev.length)return [];const d=prev.reduce((m,j)=>j.date>m?j.date:m,'');return prev.filter(j=>j.date===d);}
function unifiedSeed(date){const current=data.journals.filter(j=>j.date===date&&recordClass(j)===jClass&&hasJournalProgress(j)&&journalProgressAttended(j)),src=current.length?current:lastSessionJournals(date),tasks=new Map();src.forEach(j=>(j.tasks||[]).forEach(t=>{const text=String(t.text||'').trim();if(text&&!tasks.has(text)){const {id,done,doneAt,...fields}=t;tasks.set(text,{...fields,id:uid(),text,done:false});}}));return [...tasks.values()];}
function carryOver(sid,date,cid=jClass){if(!sid)return [];const prev=data.journals.filter(j=>j.studentId===sid&&recordClass(j)===cid&&j.date<date&&hasJournalProgress(j)&&journalProgressAttended(j)).sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];return prev?(prev.tasks||[]).filter(t=>!t.done).map(t=>({...t,id:uid(),done:false,start:t.start||'',end:t.end||''})):[];}
