function plainValue(f,r){const v=r[f.key];if(f.type==='images')return cleanImages(v).map(x=>x.url).join(' ');if(f.key==='score'&&r.passed)return 'PASS';if(f.key==='score'&&r.absent&&!r.exempt)return '缺考';if(f.type==='classes')return (v||[]).map(className).join('、');if(f.key==='score'&&r.exempt)return '不用考';if(f.type==='student')return sLabel(student(v));if(f.type==='class')return v?className(v):'';if(f.type==='checkbox')return v?'是':'';return v??'';}
function viewValue(f,r){const v=r[f.key];if(f.type==='images')return imagesThumbs(v);if(f.type==='textarea')return esc(mdPlain(v));if(f.key==='score'&&r.passed)return 'PASS';if(f.key==='score'&&r.absent&&!r.exempt)return '<span class="st absent">缺考</span>';if(f.type==='classes')return esc((v||[]).map(className).join('、'));if(f.key==='score'&&r.exempt)return '<span class="badge">不用考</span>';if(f.type==='student')return esc(sLabel(student(v)));if(f.type==='class')return v?esc(className(v)):'';if(f.type==='checkbox')return '<input type="checkbox" aria-label="'+esc(f.label)+'" data-toggle="'+esc(r.id)+'" data-field="'+f.key+'" '+(v?'checked':'')+'>';if(f.type==='url'){try{if(!/^https?:$/.test(new URL(v).protocol))return esc(v);}catch{return esc(v);}return '<a href="'+esc(v)+'" target="_blank" rel="noopener noreferrer">開啟 ↗</a>';}return esc(v);}
function genericRows(){const m=modules[page];let rows=[...data[m.key]];if(page==='成績登記')rows=rows.filter(gradeSearchMatch);
 if(filterClass)rows=rows.filter(r=>m.key==='students'?inClass(r,filterClass):recordClass(r)===filterClass);
 if(filterDate)rows=rows.filter(r=>r.date===filterDate);
 if(search&&page!=='成績登記'){const q=search.toLowerCase();rows=rows.filter(r=>rowText(r).includes(q));}
 if(m.key==='students')rows.sort((a,b)=>classOrder(a.classId)-classOrder(b.classId)||byNum(a,b));
 else if(m.key==='classes')rows=rows;
 else if(m.key==='summerSchedule'){const od='一二三四五六日',os=['全天','上午','下午','晚上'];rows.sort((a,b)=>(od.indexOf(a.weekday)-od.indexOf(b.weekday))||(os.indexOf(a.session)-os.indexOf(b.session))||classOrder(a.classId)-classOrder(b.classId));}
 else if(m.fields.some(f=>f.key==='date'))rows.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 return rows;}
