function studentNameKey(name){return String(name||'').normalize('NFKC').replace(/[\s　]+/g,'').toLowerCase();}
function duplicateStudentGroups(){const groups=new Map();data.students.forEach(s=>{const key=studentNameKey(s.name);if(!key)return;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s);});return [...groups.values()].filter(g=>g.length>1);}
function showStudentDuplicates(){if(!$('studentDuplicates')){const dialog=document.createElement('dialog');dialog.id='studentDuplicates';document.body.append(dialog);}const groups=duplicateStudentGroups();$('studentDuplicates').innerHTML='<h2>檢查重複學生</h2><p class="help">同名可能是不同學生，請先比對編號、學校與年級。選擇要保留的學生，再合併同組其他資料。</p>'+(groups.length?groups.map((group,i)=>'<section class="panel"><h3>'+esc(group[0].name)+' · '+group.length+' 筆</h3><label>保留這筆基本資料<select id="keepStudent-'+i+'">'+group.map(s=>'<option value="'+esc(s.id)+'">'+esc([s.name,s.number&&'#'+s.number,canonicalGrade(s.grade),s.school,className(s.classId),s.archived?'已離班':'在班'].filter(Boolean).join(' · '))+'</option>').join('')+'</select></label><p class="help">紀錄筆數：'+group.map(s=>esc(s.number||s.id.slice(0,6))+'：'+Object.values(data).filter(Array.isArray).reduce((n,list)=>n+list.filter(r=>r?.studentId===s.id).length,0)).join('；')+'</p><button type="button" class="primary" data-merge-students="'+i+'">合併這 '+group.length+' 筆學生</button></section>').join(''):'<p>目前沒有同名學生。</p>')+'<p class="help">合併前會下載完整 JSON 備份。所有學習紀錄保留；同日多筆紀錄不會自動刪除，可到各功能的清單查看。</p><button type="button" data-action="duplicatesClose">關閉</button>';$('studentDuplicates').showModal();}
function mergeStudentRecords(keepId,otherIds){const keep=data.students.find(s=>s.id===keepId),others=data.students.filter(s=>otherIds.includes(s.id)&&s.id!==keepId);if(!keep||!others.length)return 0;const ids=new Set(others.map(s=>s.id));const classes=[...new Set([keep.classId,...(keep.classIds||[]),...others.flatMap(s=>[s.classId,...(s.classIds||[])])].filter(Boolean))];if(!keep.classId)keep.classId=classes[0]||'';keep.classIds=classes.filter(c=>c!==keep.classId);for(const field of ['number','grade','school','contact'])if(!keep[field])keep[field]=others.find(s=>s[field])?.[field]||'';const notes=[keep.note||''];others.forEach(s=>{const differences=['number','grade','school','contact'].filter(k=>s[k]&&s[k]!==keep[k]).map(k=>({number:'原編號',grade:'原年級',school:'原學校',contact:'原聯絡資訊'}[k])+'：'+s[k]);if(s.note||differences.length)notes.push('[合併資料] '+[...differences,s.note].filter(Boolean).join('；'));});keep.note=notes.filter(Boolean).join('\n');keep.archived=!!keep.archived&&others.every(s=>s.archived);for(const list of Object.values(data))if(Array.isArray(list))for(const row of list)if(row&&ids.has(row.studentId))row.studentId=keepId;data.students=data.students.filter(s=>!ids.has(s.id));return others.length;}
function mergeStudentGroup(index){const group=duplicateStudentGroups()[index],keepId=$('keepStudent-'+index)?.value;if(!group||!group.some(s=>s.id===keepId))return;const keep=group.find(s=>s.id===keepId);if(!confirm('確認這些是同一位學生？將保留「'+keep.name+'／'+(keep.number||'未填編號')+'」，並將其他 '+(group.length-1)+' 筆的紀錄轉入。合併前會下載備份。'))return;exportData();mergeStudentRecords(keepId,group.filter(s=>s.id!==keepId).map(s=>s.id));changed();render();$('studentDuplicates').close();showStudentDuplicates();toast('已合併學生，原有紀錄皆保留。');}
