function recordCards(m,rows){const tf=m.fields.find(f=>f.key==='title')||m.fields.find(f=>f.key==='subject');
 return '<div class="rcards">'+rows.map(r=>{const id=esc(r.id),title=(tf&&r[tf.key])||'';
  const meta=m.fields.filter(f=>f!==tf&&r[f.key]&&['class','date','text','url'].includes(f.type)).map(f=>f.type==='url'?'<a href="'+esc(r[f.key])+'" target="_blank" rel="noopener noreferrer">'+esc(f.label)+' ↗</a>':'<span>'+(f.type==='date'?'📅 ':'')+viewValue(f,r)+'</span>').join('');
  const secs=m.fields.filter(f=>f.type==='textarea'&&String(r[f.key]||'').trim()).map(f=>'<div class="rcard-sec" data-reader="'+id+'" title="點一下閱讀全文"><h4>'+esc(f.label)+'</h4><p>'+esc(mdPlain(r[f.key]))+'</p></div>').join('');
  const imgs=m.fields.filter(f=>f.type==='images').map(f=>imagesThumbs(r[f.key],4)).join('');
  return '<article class="rcard"><div class="rcard-head"><h3><button type="button" class="rcard-title" data-reader="'+id+'">'+esc(title||'（未命名）')+'</button></h3><div class="actions"><button data-reader="'+id+'">閱讀</button><button data-edit="'+id+'">編輯</button><button class="danger" data-delete="'+id+'">移除</button></div></div>'+
   (meta?'<div class="rcard-meta">'+meta+'</div>':'')+(secs||'<p class="help">還沒有內容，按「編輯」開始寫。</p>')+(imgs?'<div class="rcard-imgs" data-reader="'+id+'">'+imgs+'</div>':'')+'</article>';}).join('')+'</div>';}
