 const cell=(s,d)=>rows.filter(r=>r.session===s&&r.weekday===d).map(r=>'<div class="st-course"><b>'+esc(className(r.classId)||'未分班')+'</b><span>'+esc(r.subject||'')+'</span>'+(r.teacher||r.room?'<small>'+esc([r.teacher,r.room].filter(Boolean).join(' · '))+'</small>':'')+'</div>').join('');
