/* ---------- 編輯表單 ---------- */
function studentOptions(v){const opt=s=>'<option value="'+esc(s.id)+'" '+(s.id===v?'selected':'')+'>'+esc(sLabel(s))+(s.archived?'（已離班）':'')+'</option>';const cur=v&&student(v);
 return (cur&&cur.archived?opt(cur):'')+data.classes.map(c=>{const l=classStudents(c.id);return l.length?'<optgroup label="'+esc(c.name)+'">'+l.map(opt).join('')+'</optgroup>':'';}).join('')+data.students.filter(s=>!data.classes.some(c=>c.id===s.classId)).map(opt).join('');}
function unitControl(subject,v){
 if(subject==='數學'&&data.mathUnits.length){const o=[...data.mathUnits];if(v&&!o.includes(v))o.unshift(v);return '<select name="unit" required><option value="">請選擇數學單元</option>'+o.map(x=>'<option '+(x===v?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select>';}
 return '<input name="unit" required maxlength="200" value="'+esc(v)+'" placeholder="'+(subject==='數學'?'尚未設定數學單元，可先自行輸入':'自訂單元名稱')+'">';}
function fieldControl(f,v,row){
 if(f.type==='class')return '<select name="'+f.key+'" '+(f.required?'required':'')+'><option value="">請選擇</option>'+data.classes.filter(c=>!(['值日生','清潔工作'].includes(page)&&c.online==='線上')||c.id===v).map(c=>'<option value="'+esc(c.id)+'" '+(v===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select>';
 if(f.type==='student')return '<select name="'+f.key+'" '+(f.required?'required':'')+'><option value="">請選擇</option>'+studentOptions(v)+'</select>';
 if(f.type==='classes'){const v2=Array.isArray(v)?v:[];return '<span class="checks" style="margin-top:6px">'+data.classes.map(c=>'<label class="checklabel"><input type="checkbox" name="'+f.key+'" value="'+esc(c.id)+'" '+(v2.includes(c.id)?'checked':'')+'>'+esc(c.name)+'</label>').join('')+'</span>';}
 if(f.type==='teacher'){const names=data.teachers.map(t=>t.name).filter(Boolean);if(!names.length)return '<input name="'+f.key+'" value="'+esc(v)+'" maxlength="100">';if(v&&!names.includes(v))names.unshift(v);return '<select name="'+f.key+'" '+(f.required?'required':'')+'><option value="">未指定</option>'+names.map(n=>'<option '+(n===v?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select>';}
 if(f.type==='unit')return '<span id="unitWrap">'+unitControl(row.subject||'',v)+'</span>';
 if(f.type.startsWith('select:')){const o=f.type.slice(7).split('|');if(v&&!o.includes(v))o.unshift(v);return '<select name="'+f.key+'" '+(f.required?'required':'')+'>'+(f.required&&!v?'<option value="">請選擇</option>':'')+o.map(x=>'<option '+(v===x?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select>';}
 if(f.type==='images')return imagesControl(v);
 if(f.type==='textarea')return '<textarea name="'+f.key+'" '+(f.required?'required':'')+' maxlength="20000">'+esc(v)+'</textarea>'+mdToolsHtml();
 if(f.type==='checkbox')return ' <input name="'+f.key+'" type="checkbox" '+(v?'checked':'')+'>';
 return '<input name="'+f.key+'" type="'+f.type+'" value="'+esc(v)+'" '+(f.required?'required':'')+' '+(f.type==='number'?'min="0" max="1000" step="any"':'maxlength="500"')+' '+(f.key==='score'&&row.exempt?'disabled':'')+'>';}
function openEditor(id=null){const m=modules[page];editorMode='generic';$('editor').classList.remove('dlg-wide');editId=id;const row=data[m.key].find(r=>r.id===id)||{};
 if(page==='轉班紀錄'&&id){toast('轉班為歷史紀錄；如需調整，請新增正確的轉班紀錄。');return;}
 $('formTitle').textContent=(id?'編輯':'新增')+' · '+page;
 $('fields').innerHTML=m.fields.map(f=>{const v=row[f.key]??(f.type==='date'?(f.key==='end'?'':filterDate||today()):f.type==='class'&&!id?filterClass:f.key==='gradeRule'&&!id?true:f.key==='mode'&&!id?'差異化教學':f.key==='online'&&!id?'實體':f.key==='kind'&&!id?(page==='行事曆'?'自訂放假':cKind!=='all'?cKind:''):'');
  return f.type==='images'?'<div class="wide imglabel"><span class="imglabel-title">'+esc(f.label)+'</span>'+fieldControl(f,v,row)+'</div>':'<label class="'+(f.type==='textarea'?'wide':'')+(f.type==='checkbox'?' checklabel':'')+'">'+esc(f.label)+(f.required?' *':'')+fieldControl(f,v,row)+'</label>';}).join('');initImageFields($('fields'));
 if(page==='班級資料')classFormToggle();if(page==='教材庫'&&typeof prepareMaterialEditor==='function')prepareMaterialEditor();$('editor').showModal();}
function classFormToggle(){const f=$('editForm'),on=f.elements.namedItem('online')?.value==='線上',room=f.elements.namedItem('room'),meet=f.elements.namedItem('meetUrl');if(room)room.closest('label').hidden=on;if(meet)meet.closest('label').hidden=!on;}
function submitGeneric(){const m=modules[page],old=data[m.key].find(r=>r.id===editId);const row={...old,id:editId||uid()};
 m.fields.forEach(f=>{if(f.type==='images'){row[f.key]=readImagesField($('editForm'))||[];return;}if(f.type==='classes'){row[f.key]=[...$('editForm').querySelectorAll('input[name="'+f.key+'"]:checked')].map(x=>x.value);return;}const el=$('editForm').elements.namedItem(f.key);if(!el)return;row[f.key]=f.type==='checkbox'?el.checked:el.value.trim();});
 if(m.key==='calendar'&&row.end&&row.end<row.date){toast('結束日期不可早於開始日期。');return;}
 if(m.key==='calendar'&&old?.source==='ntpc-holidays')row.source='manual';
 if(m.key==='attendance'){if(needWhy(row)&&!String(row.note||'').trim()){toast('請填寫'+row.status+'原因。');return;}if(!needWhy(row))row.note='';}
 if(m.key==='students'){row.grade=canonicalGrade(row.grade);if(!old||canonicalGrade(old.grade)!==row.grade){row.gradeSchoolYear=promotionSchoolYear();row.gradeReview=false;}}
 if(m.key==='schoolGrades'){if(row.score!==''&&!row.exempt&&(!Number.isFinite(Number(row.score))||Number(row.score)<0||Number(row.score)>100)){toast('學校評量分數須為 0～100。');return;}if(data.schoolGrades.some(g=>g.id!==row.id&&g.studentId===row.studentId&&schoolExamKey(g)===schoolExamKey(row)&&g.subject===row.subject)){toast('這位學生在此考試的科目已有成績，請編輯原紀錄。');return;}}
 if(row.exempt)row.score='';if(Array.isArray(row.classIds))row.classIds=row.classIds.filter(x=>x!==row.classId);
 if(m.key==='students'&&row.number&&data.students.some(s=>s.id!==row.id&&String(s.number||'').trim()===row.number)){toast('學生編號「'+row.number+'」已被使用，請改用其他編號。');return;}
 if(m.key==='students'){const matches=data.students.filter(s=>s.id!==row.id&&studentNameKey(s.name)===studentNameKey(row.name));if(matches.length&&!confirm('已有同名學生：'+matches.map(s=>[s.name,s.number&&'#'+s.number,s.school,canonicalGrade(s.grade)].filter(Boolean).join('／')).join('、')+'。\n如果是同一人，請取消並使用「檢查重複學生」合併。確定這是不同學生，仍要儲存？'))return;}
 if(page==='轉班紀錄'){const s=student(row.studentId);if(!s||!inClass(s,row.fromClass)||row.fromClass===row.toClass){toast('原班級須是學生目前就讀的班級，且新舊班級不可相同。');return;}if(s.classId===row.fromClass)s.classId=row.toClass;s.classIds=(s.classIds||[]).map(x=>x===row.fromClass?row.toClass:x).filter((x,i,a)=>x!==s.classId&&a.indexOf(x)===i);}
 if(['出席總覽','暑期出席與便當'].includes(page)&&data[m.key].some(r=>r.id!==row.id&&r.studentId===row.studentId&&r.date===row.date)){toast('這位學生當天已有紀錄，請編輯原紀錄。');return;}
 if(m.key==='summer')syncSummerAttendance(row,old);
 if(old)Object.assign(old,row);else data[m.key].push(row);$('editor').close();changed();render();}
function removeCalendarEntry(id){const r=data.calendar.find(x=>x.id===id);if(!r)return false;
 if(r.kind==='國定假日'&&!r.classId){if(!Array.isArray(data.meta.holidayBlocked))data.meta.holidayBlocked=[];
  const end=r.end&&r.end>=r.date?r.end:r.date;
  for(let d=r.date;d<=end;d=addDays(d,1)){if(!data.meta.holidayBlocked.includes(d))data.meta.holidayBlocked.push(d);if(data.meta.holidayBlocked.length>400)break;}}
 data.calendar=data.calendar.filter(x=>x.id!==id);return true;}
function removeRow(id){const m=modules[page];if(page==='轉班紀錄'){toast('轉班歷史保留供查詢，請新增轉班紀錄修正。');return;}
 if(m.key==='classes'&&data.students.some(s=>s.classId===id)){toast('班級仍有學生，請先轉班。');return;}
 if(m.key==='students'&&Object.values(data).some(l=>Array.isArray(l)&&l.some(r=>r&&r.studentId===id))){toast('學生已有關聯紀錄，請保留學生資料（可修改姓名或編號）。');return;}
 if(m.key==='summer'){const r=data.summer.find(x=>x.id===id);if(r){const i=data.attendance.findIndex(a=>a.studentId===r.studentId&&a.date===r.date&&a.summer);if(i>=0)data.attendance.splice(i,1);}}
 if(!confirm('確定移除此紀錄？建議先匯出備份。'))return;if(m.key==='calendar'){removeCalendarEntry(id);}else{data[m.key]=data[m.key].filter(r=>r.id!==id);}changed();render();}

