function dashboard(){const t=today(),att=data.attendance.filter(r=>r.date===t),pending=[...data.tasks,...data.admin,...data.duties].filter(x=>!x.done);
 const todays=data.students.filter(s=>allowedOn(s,t)),present=att.filter(r=>['準時','遲到','早退'].includes(r.status)).length;
 const mon=data.monitors.filter(r=>r.date===t),cln=data.cleaning.filter(r=>r.date===t);
 const last=data.meta.lastExport,stale=data.students.length&&(!last||(new Date(t)-new Date(last))/864e5>7);
 $('content').innerHTML=head('把陪伴，整理成日常。','今天 '+t+'（週'+WEEK[weekday(t)]+'）· '+(holidayOff(t,'')?holTag(holidayOff(t,'')):ruleText(t)),'<button data-action="export">↓ 匯出 JSON 備份</button>')+
 (stale?'<div class="banner">資料只存在這個瀏覽器，'+(last?'上次備份是 '+esc(last):'還沒有備份過')+'。<button data-action="export">立即備份</button></div>':'')+
 (data.classes.length?'':noClasses())+
 '<div class="cards">'+card('學生',data.students.filter(x=>!x.archived).length,data.classes.length+' 個班級')+card('今日排課',todays.length,ruleText(t))+card('今日出席',present,'已點名 '+att.length+' 位')+card('今日週誌',data.journals.filter(j=>j.date===t).length,'筆已建立')+'</div>'+
 '<section class="panel"><h2>今天，從這裡開始</h2><div class="quick">'+['學生週誌','出席總覽','學生進度','課後教學筆記','值日生','清潔工作','閱讀統計'].map(n=>'<button data-nav="'+n+'">'+n+'　↗</button>').join('')+'</div></section>'+
 '<div class="grid2"><section class="panel"><h2>班級近況</h2>'+(data.classes.length?data.classes.map(c=>{const l=classStudents(c.id);return '<div class="readitem"><strong>'+esc(c.name)+'</strong><span class="badge" style="float:right">'+l.length+' 位 · 今日 '+l.filter(s=>allowedOn(s,t,c.id)).length+' 位</span><div class="help">'+esc(c.teacher||'尚未安排老師')+'　'+esc(c.schedule||'')+'</div></div>';}).join(''):'<p class="muted">先建立班級，再加入學生。</p>')+'</section>'+
 '<section class="panel"><h2>今日值日與清潔</h2>'+(mon.length||cln.length?mon.map(r=>'<div class="readitem">'+esc(r.job||'值日生')+'：'+esc(sLabel(student(r.studentId)))+'<span class="help">　'+esc(className(r.classId))+(r.done?' · ✓':'')+'</span></div>').join('')+cln.map(r=>'<div class="readitem">清潔：'+esc(r.area)+'　'+esc(sLabel(student(r.studentId)))+'<span class="help">　'+esc(className(r.classId))+(r.done?' · ✓':'')+'</span></div>').join(''):'<p class="muted">今天尚未安排值日生或清潔工作。</p>')+'<h2 style="margin-top:20px">待辦提醒</h2>'+(pending.length?pending.slice(0,8).map(x=>'<div class="readitem">'+esc(x.title)+'<div class="help">'+esc(x.date)+'　'+esc(x.person||'')+'</div></div>').join(''):'<p class="muted">目前沒有待辦，留點時間給自己。</p>')+'</section></div>';}

