const chip=r=>'<span class="chip t'+READ_TYPES.indexOf(r.type)+(r.done?'':' undone')+'">'+esc(r.type)+'｜'+(r.bookId?esc(r.bookId)+' ':'')+esc(r.title||'未填書名')+(r.bookType&&r.bookType!==r.type?'・'+esc(r.bookType):'')+(r.done?' ✓':'（未勾選）')+'</span>';
function dayJournals(){return data.journals.filter(j=>j.date===jDate&&recordClass(j)===jClass);}
function journalRows(){if(jView==='day')return dayJournals();let rows=data.journals.filter(j=>(!filterClass||recordClass(j)===filterClass)&&(!jMonth||String(j.date).startsWith(jMonth)));if(search){const q=search.toLowerCase();rows=rows.filter(r=>rowText(r).includes(q));}return rows.sort((a,b)=>String(b.date).localeCompare(a.date)||byNum(student(a.studentId)||{},student(b.studentId)||{}));}
