function englishTaskData(t){const option=t.option||(ENGLISH_TASKS.includes(t.text)?t.text:'自訂');return {...t,option,lesson:t.lesson||'',detail:t.detail??(option==='自訂'?t.text||'':'')};}
function formatAssessmentPaper(text){return String(text??'').replace(/(檢測卷\s*)([1-4１-４])(?![\d０-９])/g,(_,label,n)=>label+'①②③④'[Number(n.normalize('NFKC'))-1]);}
function assessmentProgressOption(value,current){return '<option value="'+esc(value)+'" '+(value===current?'selected':'')+'>'+esc(formatAssessmentPaper(value))+'</option>';}
function englishTaskText(t){return [t.lesson?'L'+t.lesson:'',t.option==='自訂'?t.detail:[t.option,t.detail].filter(Boolean).join(' · ')].filter(Boolean).join(' ');}
function englishTaskCard(t){t=englishTaskData(t);return '<div class="english-task" data-row="task" data-id="'+esc(t.id||uid())+'"><div class="english-task-head"><label class="checklabel"><input type="checkbox" class="task-done" '+(t.done?'checked':'')+'><span>第 <span class="task-number">1</span> 項 · 已完成</span></label><div class="actions"><button type="button" data-task-move="up" aria-label="上移這一項">↑</button><button type="button" data-task-move="down" aria-label="下移這一項">↓</button><button type="button" data-action="delRow">移除</button></div></div><div class="english-task-grid"><label>課次 N<input class="task-lesson" type="number" min="1" step="1" value="'+esc(t.lesson)+'" placeholder="例如：1"></label><label>進度選項<select class="task-option">'+[...ENGLISH_TASKS,'自訂'].map(o=>assessmentProgressOption(o,t.option)).join('')+'</select></label><label>開始時間<input type="time" class="tstart" value="'+esc(t.start||'')+'"></label><label>結束時間<input type="time" class="tend" value="'+esc(t.end||'')+'"></label><label class="wide"><span class="task-detail-label">'+(t.option==='自訂'?'自訂進度':'補充內容／頁碼')+'</span><textarea class="task-detail" maxlength="500" placeholder="填寫進度內容或頁碼">'+esc(t.detail)+'</textarea></label></div><label class="checklabel"><input type="checkbox" class="task-help" '+(t.needsHelp?'checked':'')+'> ⭐ 老師需要協助</label><input type="text" hidden class="task-text" value="'+esc(englishTaskText(t))+'"></div>';}
function readEnglishTask(row){const t={id:row.dataset.id,lesson:row.querySelector('.task-lesson').value,option:row.querySelector('.task-option').value,detail:row.querySelector('.task-detail').value.trim(),start:row.querySelector('.tstart').value,end:row.querySelector('.tend').value,done:row.querySelector('.task-done').checked,needsHelp:row.querySelector('.task-help').checked};return {...t,text:englishTaskText(t)};}
const MATH_TASKS=['單元','非數','檢測 1','檢測 2','檢測 3','檢測 4','練習卷','自訂'];
const READING_TASKS=['每週國內外大事','KIST','大量閱讀','文字書','繪本','橋樑書','自訂'];
function readingTaskText(t){return t.option==='每週國內外大事'?'每週國內外大事'+(t.issue?' 第'+t.issue+'期':''):[t.option==='自訂'?'':t.option,t.detail].filter(Boolean).join(' · ');}
function readingTaskCardBase(t={}){const option=READING_TASKS.includes(t.option)?t.option:t.text?'自訂':'每週國內外大事',detail=t.detail??(option==='自訂'?t.text||'':'');return '<div class="english-task reading-task" data-row="task" data-id="'+esc(t.id||uid())+'"><div class="english-task-head"><label class="checklabel"><input type="checkbox" class="task-done" '+(t.done?'checked':'')+'><span>第 <span class="task-number">1</span> 項 · 已完成</span></label><div class="actions"><button type="button" data-task-move="up" aria-label="上移這一項">↑</button><button type="button" data-task-move="down" aria-label="下移這一項">↓</button><button type="button" data-action="delRow">移除</button></div></div><div class="english-task-grid"><label>快捷選項<select class="task-option">'+READING_TASKS.map(o=>'<option '+(o===option?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select></label><label class="task-issue-wrap" '+(option==='每週國內外大事'?'':'hidden')+'>第幾期<input type="number" class="task-issue" min="1" step="1" value="'+esc(t.issue||'')+'" placeholder="例如：26"></label><label class="task-reading-detail" '+(option==='每週國內外大事'?'hidden':'')+'><span class="task-detail-label">'+(option==='自訂'?'自訂進度':'書名／篇名')+'</span><textarea class="task-detail" maxlength="500">'+esc(detail)+'</textarea></label><label>開始時間<input type="time" class="tstart" value="'+esc(t.start||'')+'"></label><label>結束時間<input type="time" class="tend" value="'+esc(t.end||'')+'"></label></div><label class="checklabel"><input type="checkbox" class="task-help" '+(t.needsHelp?'checked':'')+'> ⭐ 老師需要協助</label><p class="task-summary help" aria-live="polite">'+esc([tTime(t),readingTaskText({...t,option,detail})].filter(Boolean).join('　'))+'</p><input type="text" hidden class="task-text" value="'+esc(readingTaskText({...t,option,detail}))+'"></div>';}
function kistGradeOptions(level,selectedId=''){const rows=kistList().filter(k=>String(k.level)===String(level));return '<option value="">'+(!level?'請先選擇年級':rows.length?'請選擇課次（共 '+rows.length+' 課）':'此年級尚無課程，可到資料設定新增')+'</option>'+rows.map(k=>'<option value="'+esc(k.id)+'" '+(selectedId===k.id?'selected':'')+'>'+esc(k.title)+(k.strategy?' · '+esc(k.strategy):'')+'</option>').join('');}
function readingTaskKistCard(t={}){const selected=kistList().find(k=>k.id===t.kistId||k.title===t.detail),level=String(t.kistLevel||selected?.level||'');const picker='<div class="wide task-kist-wrap" '+(t.option==='KIST'?'':'hidden')+'><div class="english-task-grid"><label>KIST 年級<select class="task-kist-level"><option value="">請選擇年級</option>'+[4,5,6,7,8,9].map(n=>'<option value="'+n+'" '+(level===String(n)?'selected':'')+'>'+n+' 年級</option>').join('')+'</select></label><label>KIST 課程清單<select class="task-kist" '+(!level?'disabled':'')+'>'+kistGradeOptions(level,selected?.id||'')+'</select></label></div></div>';return readingTaskCardBase(t).replace('<label>開始時間',picker+'<label>開始時間');}
document.addEventListener('change',e=>{if(!e.target.classList.contains('task-kist-level'))return;const row=e.target.closest('.reading-task'),picker=row.querySelector('.task-kist'),level=e.target.value;picker.innerHTML=kistGradeOptions(level);picker.disabled=!level;row.querySelector('.task-detail').value='';refreshJournalCard(row);});
function readReadingTask(row){const option=row.querySelector('.task-option').value,kistId=row.querySelector('.task-kist')?.value||'',k=option==='KIST'&&kistList().find(x=>x.id===kistId&&String(x.level)===row.querySelector('.task-kist-level').value);const t={id:row.dataset.id,option,issue:row.querySelector('.task-issue').value,detail:k?k.title:option==='大量閱讀'?row.querySelector('.booktitle').value.trim():row.querySelector('.task-detail').value.trim(),bookId:option==='大量閱讀'?row.dataset.bookid||'':'',bookType:option==='大量閱讀'?row.dataset.booktype||'':'',kistId:option==='KIST'&&k?kistId:'',kistLevel:option==='KIST'?row.querySelector('.task-kist-level').value:'',start:row.querySelector('.tstart').value,end:row.querySelector('.tend').value,done:row.querySelector('.task-done').checked,needsHelp:row.querySelector('.task-help').checked};return {...t,text:readingTaskText(t)};}
function readingTaskCard(t={}){const picker='<label class="wide task-book-wrap" '+(t.option==='大量閱讀'?'':'hidden')+'>搜尋書碼／書名<span class="bookpick"><input type="text" class="booktitle" maxlength="300" value="'+esc(t.option==='大量閱讀'?t.detail||'':'')+'" placeholder="例如 C0834，或輸入書名" autocomplete="off" aria-label="搜尋書碼或書名" aria-autocomplete="list" aria-expanded="false"><span class="booksug" role="listbox" hidden></span></span><span class="help task-book-meta">'+esc([t.bookId,t.bookType].filter(Boolean).join(' · '))+'</span></label>';return readingTaskKistCard(t).replace('class="english-task reading-task"','class="english-task reading-task" data-bookid="'+esc(t.bookId||'')+'" data-booktype="'+esc(t.bookType||'')+'"').replace('<label>開始時間',picker+'<label>開始時間');}
function readJournalCard(row){return row.classList.contains('reading-task')?readReadingTask(row):row.classList.contains('math-task')?readMathTask(row):readEnglishTask(row);}
function refreshJournalCard(row){const task=readJournalCard(row);row.querySelector('.task-text').value=task.text;if(row.classList.contains('reading-task')){row.querySelector('.task-issue-wrap').hidden=task.option!=='每週國內外大事';row.querySelector('.task-reading-detail').hidden=task.option==='每週國內外大事'||task.option==='KIST'||task.option==='大量閱讀';if(row.querySelector('.task-book-wrap'))row.querySelector('.task-book-wrap').hidden=task.option!=='大量閱讀';if(row.querySelector('.task-kist-wrap'))row.querySelector('.task-kist-wrap').hidden=task.option!=='KIST';if(task.option==='KIST'&&task.kistId)row.querySelector('.task-detail').value=task.detail;row.querySelector('.task-detail-label').textContent=task.option==='自訂'?'自訂進度':'書名／篇名';row.querySelector('.task-summary').textContent=[tTime(task),task.text].filter(Boolean).join('　');}else row.querySelector('.task-detail-label').textContent=task.option==='自訂'?'自訂進度':'補充內容／頁碼';}
document.addEventListener('input',e=>{const row=e.target.closest?.('.english-task');if(row){if(e.target.classList.contains('booktitle')){row.dataset.bookid='';row.dataset.booktype='';row.querySelector('.task-book-meta').textContent='';}refreshJournalCard(row);}});
function mathTaskText(t){return [t.option==='自訂'?'':t.option,t.unit,t.pages?'頁數 '+t.pages:'',t.detail].filter(Boolean).join(' · ');}
function mathTaskCard(t={}){const option=MATH_TASKS.includes(t.option)?t.option:t.text?'自訂':'單元',detail=t.detail??(option==='自訂'?t.text||'':'');let card=englishTaskCard({...t,option:'自訂',detail});card=card.replace('class="english-task"','class="english-task math-task"');card=card.replace(/課次 N<input[^>]+>/,'單元<input class="task-unit" type="text" maxlength="100" value="'+esc(t.unit||'')+'" placeholder="例如：5-1、5-2">');card=card.replace(/<select class="task-option">[\s\S]*?<\/select>/,'<select class="task-option">'+MATH_TASKS.map(o=>'<option '+(o===option?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select>');card=card.replace('<label>開始時間','<label class="wide">頁數<input class="task-pages" type="text" maxlength="100" value="'+esc(t.pages||'')+'" placeholder="例如：12–15、18、20"></label><label>開始時間');card=card.replace('自訂進度</span>','補充內容／自訂進度</span>');return card;}
function readMathTask(row){const t={id:row.dataset.id,unit:row.querySelector('.task-unit').value.trim(),pages:row.querySelector('.task-pages').value.trim(),option:row.querySelector('.task-option').value,detail:row.querySelector('.task-detail').value.trim(),start:row.querySelector('.tstart').value,end:row.querySelector('.tend').value,done:row.querySelector('.task-done').checked,needsHelp:row.querySelector('.task-help').checked};return {...t,text:mathTaskText(t)};}
function taskRow(t={}){const tm=editorMode==='journal';if(tm&&classById(journalClassId)?.kind==='英文')return englishTaskCard(t);if(tm&&classById(journalClassId)?.kind==='數學')return mathTaskCard(t);if(tm&&classById(journalClassId)?.kind==='閱讀')return readingTaskCard(t);return '<div class="rowedit trow'+(tm?' timed':'')+'" data-row="task" data-id="'+esc(t.id||uid())+'"><label class="tick"><input type="checkbox" aria-label="已完成" '+(t.done?'checked':'')+'><span aria-hidden="true"></span></label>'+(tm?'<span class="tslot"><input type="time" class="tstart" value="'+esc(t.start||'')+'" aria-label="開始時間"><i>–</i><input type="time" class="tend" value="'+esc(t.end||'')+'" aria-label="結束時間"></span>':'')+'<input type="text" maxlength="500" placeholder="例如：L19 workbook R1" value="'+esc(t.text||'')+'" aria-label="進度項目"><button type="button" class="rowdel" data-action="delRow" aria-label="移除這一項">✕</button></div>';}
const tTime=t=>t&&(t.start||t.end)?(t.start||'')+'–'+(t.end||''):'';
const sortTasks=a=>a.some(t=>t.option)?[...a]:[...a].map((t,i)=>[t,i]).sort((x,y)=>(x[0].start||'99').localeCompare(y[0].start||'99')||x[1]-y[1]).map(x=>x[0]);
function readRow(r={}){return '<div class="rowedit rrow" data-row="reading" data-id="'+esc(r.id||uid())+'" data-bookid="'+esc(r.bookId||'')+'"><select aria-label="閱讀類型">'+READ_TYPES.map(o=>'<option '+((r.type||'大量閱讀')===o?'selected':'')+'>'+o+'</option>').join('')+'</select><select aria-label="書籍類型" title="書籍類型（大量閱讀的書可另計入文字書／繪本／橋樑書）" '+(['KIST','國內外大事'].includes(r.type)?'disabled':'')+'><option value="">書籍類型—</option>'+['文字書','繪本','橋樑書'].map(o=>'<option '+(r.bookType===o?'selected':'')+'>'+o+'</option>').join('')+'</select><span class="bookpick"><input type="text" class="booktitle" maxlength="300" placeholder="書碼或書名，例如 C0834" value="'+esc(r.title||'')+'" autocomplete="off" aria-autocomplete="list" aria-label="書名／篇名（可輸入書碼搜尋圖書館）"><span class="booksug" role="listbox" hidden></span></span><label class="countit"><input type="checkbox" '+(r.done?'checked':'')+'><span>納入統計</span></label><button type="button" class="rowdel" data-action="delRow" aria-label="移除這本">✕</button></div>';}
