function journalHistorySummary(j){const tasks=(j.tasks||[]).map(t=>t.text||'').filter(Boolean),readings=(j.readings||[]).map(r=>r.title||'').filter(Boolean),summary=tasks.length?tasks.join('、'):j.content||readings.join('、')||j.subject||'尚未填寫進度';return formatAssessmentPaper(summary).replace(/\s+/g,' ').slice(0,110);}
function journalHistoryPreviewHtml(j){const tasks=j.tasks||[],readings=j.readings||[];return '<div class="jhistory-preview-heading"><strong>'+esc(j.date)+' · 進度內容</strong><span>'+esc([j.startTime,j.endTime].filter(Boolean).join('–'))+'</span></div>'+(j.subject?'<p class="jhistory-subject">'+esc(j.subject)+'</p>':'')+(j.content?'<div class="jhistory-content">'+esc(j.content)+'</div>':'')+(tasks.length?'<h4>進度清單</h4><ul>'+tasks.map(t=>'<li><span class="jhistory-check '+(t.done?'done':'')+'">'+(t.done?'✓':'○')+'</span><div>'+(tTime(t)?'<small>'+esc(tTime(t))+'</small>':'')+'<span>'+esc(formatAssessmentPaper(t.text||'未填進度'))+'</span>'+(t.needsHelp?'<em>需要協助</em>':'')+'</div></li>').join('')+'</ul>':'')+(readings.length?'<h4>閱讀資料</h4><ul>'+readings.map(r=>'<li><span class="jhistory-check '+(r.done?'done':'')+'">'+(r.done?'✓':'○')+'</span><div><small>'+esc([r.type,r.bookId].filter(Boolean).join(' · '))+'</small><span>'+esc(r.title||'未填書名')+'</span></div></li>').join('')+'</ul>':'')+(!tasks.length&&!readings.length&&!j.content?'<p class="help">這筆紀錄尚未填寫進度內容。</p>':'');}
function showJournalHistoryPreview(){const box=$('journalHistoryPreview');if(!box)return;const id=$('journalHistory')?.value,source=data.journals.find(j=>j.id===id&&j.studentId===journalStudent&&recordClass(j)===journalClassId);box.hidden=!source;box.innerHTML=source?journalHistoryPreviewHtml(source):'';}
