function fillJournalHistory(mode){const id=$('journalHistory')?.value,source=data.journals.find(x=>x.id===id&&x.studentId===journalStudent&&recordClass(x)===journalClassId);if(!source){toast('請先選擇歷史紀錄。');return;}const f=$('editForm');if(mode==='content'){const keys=['startTime','endTime','subject','content'];if(keys.some(k=>f.elements.namedItem(k)?.value)&&!confirm('要以選取的歷史紀錄取代目前時間與學習內容嗎？'))return;keys.forEach(k=>{const el=f.elements.namedItem(k);if(el)el.value=source[k]||'';});}else if(mode==='tasks'){const existing=new Set([...$('taskRows').querySelectorAll('input[type=text]')].map(el=>el.value.trim()));$('taskRows').insertAdjacentHTML('beforeend',(source.tasks||[]).filter(t=>!existing.has(t.text.trim())).map(t=>taskRow({...t,id:uid(),done:false})).join(''));updateTaskCount();}else if(mode==='readings'){const existing=new Set([...$('readRows').querySelectorAll('.booktitle')].map(el=>normTitle(el.value)));$('readRows').insertAdjacentHTML('beforeend',(source.readings||[]).filter(r=>!existing.has(normTitle(r.title))).map(r=>readRow({...r,id:uid(),done:false})).join(''));}toast('已帶入，可修改後按完成儲存。');}
