 const j=data.journals.find(x=>x.id===id)||{tasks:[],readings:[]};journalStudent=j.studentId||sid||'';journalClassId=id?recordClass(j):(jClass||student(journalStudent)?.classId||'');const date=j.date||jDate,s=student(journalStudent),c=classById(journalClassId),uni=isUnified(journalClassId);
