 progChecks.forEach(c=>{const rec=data.progress.find(x=>x.id===c.rec),t=rec&&rec.tasks.find(x=>x.id===c.tid);if(t&&t.done!==c.done){t.done=c.done;if(c.done)t.doneAt=date;else delete t.doneAt;rec.done=rec.tasks.length>0&&rec.tasks.every(x=>x.done);if(String(date)>String(rec.date||''))rec.date=date;}});
