function collectJournalGrades(){const box=$('jGradeRows');if(!box)return {ops:[],del:[]};const ops=[];
 for(const r of box.querySelectorAll('[data-row=grade]')){const sec=r.querySelector('.gsec').value,title=r.querySelector('.gtitle').value.trim(),paper=['檢測','數學檢測'].includes(sec)?r.querySelector('.gpaper').value:'',p=gParse(r.querySelector('.gscore').value);
  if(p===undefined){toast('成績請輸入 0–1000 的分數、PASS（通過），或「缺」「免」。');r.querySelector('.gscore').focus();return false;}
  if(p===null){if(r.dataset.gid)ops.push({del:r.dataset.gid});continue;}
  if(!title){toast('請填寫評量名稱。');r.querySelector('.gtitle').focus();return false;}ops.push({gid:r.dataset.gid,sec,title,paper,p});}
 return {ops,del:(box.dataset.del||'').split(',').filter(Boolean)};}
function applyJournalGrades(res,sid,date,cls){res.del.forEach(id=>{data.grades=data.grades.filter(g=>g.id!==id);});
 res.ops.forEach(o=>{if(o.del){data.grades=data.grades.filter(g=>g.id!==o.del);return;}const title=o.sec==='單字檢定'?o.title.replace(/^(基礎|成長)\s*(\d+)$/,'$1$2'):o.title,isRead=title==='認讀卷';
  let ex=o.gid&&data.grades.find(g=>g.id===o.gid);if(!ex)ex=data.grades.find(g=>g.studentId===sid&&g.date===date&&g.section===o.sec&&normTitle(g.title)===normTitle(title)&&(g.paper||'')===o.paper);
  const base={section:o.sec,title,paper:o.paper,date};if(ex)Object.assign(ex,base,o.p);else data.grades.push({id:uid(),studentId:sid,classId:cls||'',subject:gClassSubject(cls),maxScore:isRead?'50':'100',passScore:isRead?'40':o.paper==='B'?'60':'80',note:'',exempt:false,absent:false,...base,...o.p});});}
function linkProgress(sid,date){const jj=data.journals.find(x=>x.studentId===sid&&recordClass(x)===journalClassId&&x.date===date);if(!jj)return 0;const done=new Set(jj.tasks.filter(t=>t.done).map(t=>normTitle(t.text)));let n=0;
 pCurrent(sid).cur.forEach(rec=>{let ch=false;(rec.tasks||[]).forEach(t=>{if(!t.done&&done.has(normTitle(t.text))){t.done=true;t.doneAt=date;ch=true;n++;}});if(ch){rec.done=rec.tasks.every(t=>t.done);if(String(date)>String(rec.date||''))rec.date=date;}});return n;}
function cardLinks(sid,date){const pc=pCurrent(sid).cur,gd=data.grades.filter(g=>g.studentId===sid&&g.date===date);if(!pc.length&&!gd.length)return '';
 return '<div class="jlinks">'+pc.map(r=>{const t=r.tasks||[];return '<span class="jl" title="學生進度"><span class="kdot k-'+(SUBJ_CLS[r.subject]||'other')+'"></span>'+esc((r.subject||'')+' '+(r.unit||''))+' <b>'+(t.length?t.filter(x=>x.done).length+'/'+t.length:(r.done?'✓':''))+'</b></span>';}).join('')+gd.map(g=>{let v=gCellVal(g);if(g.exempt&&g.section==='單字檢定'){const lv=vocabLevelOf(sid);v=(lv.next||lv.passed)?'目前 '+(lv.next||lv.passed):'免';}return '<span class="jl st '+gStatus(g)[0]+'" title="今日成績'+(g.exempt?'（免考）':'')+'">'+esc(gTitle(g))+' '+esc(v)+'</span>';}).join('')+'</div>';}
function obsHistHtml(sid,curId){if(!sid)return '';const items=data.weeklyObs.filter(x=>x.studentId===sid&&obsSubjectOf(x)===obsContextSubject()&&x.id!==curId&&(x.note||x.next)).sort((a,b)=>String(b.week).localeCompare(String(a.week)));
 if(!items.length)return '<p class="help" style="margin-top:10px">這位學生還沒有其他週的觀察紀錄。</p>';
 return '<div class="obshist"><div class="obshist-head"><h4>其他週的觀察與後續 <span class="jcount">'+items.length+' 週</span></h4><button type="button" class="iconbtn" data-obs="'+esc(sid)+'">查看全部／複製</button></div>'+items.slice(0,6).map(x=>'<div class="obsitem"><div class="obsdate">'+esc(weekLabel(x.week))+' · '+esc(className(x.classId||student(x.studentId)?.classId))+'</div>'+(x.note?'<p><b>觀察</b>'+esc(x.note)+'</p>':'')+(x.next?'<p><b>後續</b>'+esc(x.next)+'</p>':'')+'<div class="obsuse">'+(x.note?'<button type="button" class="linkbtn" data-obsuse="note|'+esc(x.id)+'">帶入觀察</button>':'')+(x.next?'<button type="button" class="linkbtn" data-obsuse="next|'+esc(x.id)+'">帶入後續</button>':'')+'</div></div>').join('')+(items.length>6?'<button type="button" class="addrow" data-obs="'+esc(sid)+'">查看全部 '+items.length+' 週</button>':'')+'</div>';}
let obsSubject='英文',obsSid='',obsFrom='',obsTo='',obsNext=true,obsDedupe=true,obsMode='sorted';const obsOverride={};
// 由新到舊
function obsEntries(sid){let prev=null;return data.weeklyObs.filter(w=>w.studentId===sid&&obsSubjectOf(w)===obsSubject&&(w.note||w.next)&&(!obsFrom||addDays(w.week,6)>=obsFrom)&&(!obsTo||w.week<=obsTo)).sort((a,b)=>String(b.week).localeCompare(String(a.week))).filter(w=>{const k=(w.note||'')+'|'+(obsNext?w.next||'':'');if(obsDedupe&&prev===k)return false;prev=k;return obsNext||w.note;});}
// 整理：依關鍵字把觀察分成學習表現／行為表現
const OBS_BEH=/分心|聊天|說話|講話|吵|鬧|坐不住|唱歌|配合|態度|禮貌|脾氣|情緒|專心|專注|積極|主動|參與|上台|舉手|發言|起鬨|勸|提醒|罵|睡覺|想睡|不想寫|不太想|不願|被動|散漫|互動|合作|秩序|安靜|害羞|自信|表演|獎勵|加點|規矩|坐姿|站在|轉頭|心不在焉|耐心|玩|留下|唱|吵架|說別人|交代了事|小聰明|看解答|洗臉/g;
const OBS_LEARN=/單字|文法|句|書寫|寫字|字體|閱讀|讀|理解|計算|算式|算|題|錯誤|錯|背誦|背|練習|進度|檢測|測驗|考|分數|心得|拼音|發音|念|認讀|應用|乘法|除法|加減|分母|因數|倍數|觀念|概念|掌握|熟悉|複習|訂正|課本|習作|workbook|動詞|時態|翻譯|思考|表達|論述|重點|統整|學習|吸收|教導|書本|作文|英文|數學|國語|L\d/gi;
const obsScore=(t,re)=>(String(t).match(re)||[]).length;
function obsItems(text){const out=[];String(text||'').split(/[。！？!?；;\n]+/).map(x=>x.trim()).filter(Boolean).forEach(sen=>{const cl=sen.split(/[，,]/).map(x=>x.trim()).filter(Boolean);let cats=cl.map(c=>{const b=obsScore(c,OBS_BEH),l=obsScore(c,OBS_LEARN);return b>l?'beh':l>b?'learn':b&&l?'learn':'';});
  const first=cats.find(Boolean)||'learn';cats=cats.map((c,i)=>c||(i?null:first));for(let i=0;i<cats.length;i++)if(cats[i]===null)cats[i]=cats[i-1];
  cl.forEach((c,i)=>{const last=out[out.length-1];if(last&&last.cat===cats[i]&&last.sen===sen)last.text+='，'+c;else out.push({cat:cats[i],text:c,sen});});});
 return out.map(o=>{o.text=o.text.replace(/^(並且|並|而且|且|也)(?=.)/,'');const key=normTitle(o.text);return {cat:obsOverride[key]||o.cat,text:o.text,key};});}
function obsOrganize(list){const res={learn:[],beh:[],next:[]},seen=new Set();list.forEach(w=>{obsItems(w.note).forEach(it=>{if(seen.has(it.key))return;seen.add(it.key);res[it.cat].push({...it,week:w.week});});
  if(obsNext)String(w.next||'').split(/[。！？!?；;\n]+/).map(x=>x.trim()).filter(Boolean).forEach(t=>{const key='n:'+normTitle(t);if(seen.has(key))return;seen.add(key);res.next.push({text:t,key,week:w.week});});});return res;}
const OBS_PROMPT='請幫我將以下的學生觀察記錄統整成一段完整的評語。請嚴格遵守以下條件：\n1. 不要出現任何日期、週次或時間。\n2. 不要出現任何班級名稱。\n3. 將內容清楚分為「學習表現」與「行為表現」兩大類來呈現。\n4. 融合各週重點，寫出學生整體的表現、遇到的困難及需要加強的地方。\n\n【觀察記錄】\n';
function obsSortedText(withDates){const o=obsOrganize(obsEntries(obsSid)),sec=(t,a)=>a.length?t+'：\n'+a.map((x,i)=>(i+1)+'. '+x.text+(withDates?'（'+weekLabel(x.week)+'）':'')).join('\n'):'';return [sec('學習表現',o.learn),sec('行為表現',o.beh),sec('後續協助',o.next)].filter(Boolean).join('\n\n');}
function obsText(withPrompt){if(withPrompt)return OBS_PROMPT+obsSortedText(false);if(obsMode==='sorted')return obsSortedText(true);
 return obsEntries(obsSid).map(w=>['【'+weekLabel(w.week)+'】',w.note&&'觀察：'+w.note,obsNext&&w.next&&'後續：'+w.next].filter(Boolean).join('\n')).join('\n\n');}
