  '<div class="dialogfoot"><button type="button" class="danger" data-attset="">清除紀錄</button><div class="actions"><button type="button" data-action="attClose">取消</button><button type="button" class="primary" data-action="attSave"'+(attPick?'':' disabled')+'>儲存</button></div></div>';
