document.addEventListener('pointerup',e=>{const p=press;press=null;if(!p)return;clearTimeout(p.timer);if(p.long)return;const b=e.target.closest?.('.att-cell[data-att-s]');if(b!==p.b)return;const k=b.dataset.attS+'|'+b.dataset.attD,now=Date.now();if(lastTap.k===k&&now-lastTap.t<450){lastTap={k:'',t:0};quickMark(b.dataset.attS,b.dataset.attD);}else lastTap={k,t:now};});
