/* ---------- 閱讀統計 ---------- */
function readingBookCategory(...values){for(const value of values){const text=String(value||'').normalize('NFKC').trim().toUpperCase(),match=/^([ABC])(?:\d|$|[\s_-]+\d)/.exec(text);if(match)return {A:'繪本',B:'橋樑書',C:'文字書'}[match[1]];}return '';}
function journalReadingItems(j){const entries=new Map();const add=(type,title,done,bookType,bookId='')=>{title=String(title||'').trim();if(!title||!READ_TYPES.includes(type))return;for(const category of [...new Set([type,bookType].filter(t=>READ_TYPES.includes(t)))]){const key=category+'|'+normTitle(title),old=entries.get(key);entries.set(key,{studentId:j.studentId,type:category,title,bookId:bookId||old?.bookId||'',date:j.date,done:!!done||!!old?.done});}};
 (j.readings||[]).forEach(r=>{const category=readingBookCategory(r.bookId,r.title);add(category||r.type,r.title||r.bookId,r.done,category?'':r.bookType,r.bookId);});
 (j.tasks||[]).forEach(t=>{const type=t.option==='每週國內外大事'?'國內外大事':t.option;if(!READ_TYPES.includes(type))return;const title=type==='國內外大事'&&t.issue?'每週國內外大事 第'+t.issue+'期':t.detail||t.bookId||'',category=readingBookCategory(t.bookId,title);add(category||type,title,t.done,category?'':type==='大量閱讀'?t.bookType:'',t.bookId);});return [...entries.values()];}
function readingClasses(){return data.classes.filter(c=>c.kind==='閱讀');}
function readingStudents(){const classes=readingClasses();return classStudents(rClass).filter(s=>classes.some(c=>(!rClass||c.id===rClass)&&inClass(s,c.id)));}
function readingClassSelect(){return '<select id="rClass"><option value="">全部閱讀班</option>'+readingClasses().map(c=>'<option value="'+esc(c.id)+'" '+(rClass===c.id?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select>';}
function readingStudentClassLabel(s){return readingClasses().filter(c=>(!rClass||c.id===rClass)&&inClass(s,c.id)).map(c=>c.name).join('、');}
