 const identity=s=>'<div class="reading-student"><button class="personal-reading-link" data-personal-reader="'+esc(s?.id||'')+'">'+esc(s?.name||'原學生')+'</button><small>'+esc([s?.number&&'#'+s.number,s?.grade&&canonicalGrade(s.grade)].filter(Boolean).join(' · '))+'</small></div>';
