 const section=(title,hint,types)=>'<section class="reading-overview"><div class="reading-section-head"><h2>'+title+'</h2><p class="help">'+hint+'</p></div><div class="reading-metrics" style="grid-template-columns:repeat('+types.length+',minmax(0,1fr))">'+types.map((t,i)=>'<article class="reading-metric metric-'+i+'"><span>'+t+'</span><strong>'+cnt(t)+'<small>'+READ_UNIT[t]+'</small></strong><p>已完成</p></article>').join('')+'</div></section>';
 const ordered=[...rows].sort((a,b)=>byNum(student(a.studentId)||{},student(b.studentId)||{})||READ_TYPES.indexOf(a.type)-READ_TYPES.indexOf(b.type));
