const gCellVal=g=>!g?'':g.exempt?'免':g.absent?'缺':g.passed?'PASS':(g.score??'');
function gParse(v){v=String(v).trim();if(!v)return null;if(/^(PASS|通過)$/i.test(v))return {passed:true,absent:false,exempt:false,score:''};if(/^(缺|缺考)$/.test(v))return {passed:false,absent:true,exempt:false,score:''};if(/^(免|不用考|-|—)$/.test(v))return {passed:false,exempt:true,absent:false,score:''};const n=Number(v);if(!isFinite(n)||n<0||n>1000)return undefined;return {score:String(n),passed:false,absent:false,exempt:false};}
function gCell(ck,g,attrs,ri,col,label,att){const st=g?gStatus(g):['none','未登記'],mk={good:'✓',mid:'△',low:'✕'}[st[0]]||'',lv=!g&&att&&isLeaveAtt(att);
 return '<td class="gc"><span class="gcw"><input class="gcell s-'+st[0]+(lv?' s-attleave':'')+'"'+(lv?' placeholder="'+esc(att.status)+'"':'')+(g&&att&&isLeaveAtt(att)?' data-att="'+esc(att.status)+'"':'')+' data-grade-id="'+esc(g?.id||'')+'" data-ck="'+esc(ck)+'" data-ri="'+ri+'" data-col="'+esc(col)+'" '+attrs+' value="'+esc(gCellVal(g))+'" inputmode="decimal" autocomplete="off" aria-label="'+esc(label+'：'+st[1])+'" title="'+esc(label+(g&&g.date&&!String(label).includes(g.date)?'　'+g.date:'')+'　'+st[1]+'　長按可編輯完整資料（電腦亦可按 F2）'+(g&&g.note?'：'+g.note:'')+(g&&g._n>1?'（共 '+g._n+' 次）':'')+(att&&att.status!=='準時'?'　出席：'+att.status+(attWhy(att)?'（'+attWhy(att)+'）':''):''))+'"><span class="cm" aria-hidden="true">'+(lv?'':mk)+'</span>'+(att&&isLeaveAtt(att)?'<span class="gatt k-'+(ATT_CODE[att.status]||['none'])[0]+'" aria-hidden="true">'+esc(String(att.status).slice(0,1))+'</span>':'')+'</span></td>';}
const isLeaveAtt=a=>a&&['病假','事假','公假','請假','缺席','長假'].includes(a.status);
const attOn=(sid,date)=>data.attendance.find(a=>a.studentId===sid&&a.date===date);
function attChip(a){return a&&needWhy(a)?'<span class="attst k-'+(ATT_CODE[a.status]||['none'])[0]+'" title="'+esc(a.status+(attWhy(a)?'：'+attWhy(a):''))+'">'+esc(a.status)+(a.note?'・'+esc(a.note):'')+'</span>':'';}
function gLatest(list){if(!list.length)return null;const l=[...list].sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];l._n=list.length;return l;}
function gClassSubject(cls){const ck=data.classes.find(c=>c.id===cls)?.kind;if(ck==='數學')return '數學';if(ck==='英文'||ck==='PASSION')return '英文';if(ck==='閱讀')return '閱讀';const c=new Map();data.grades.forEach(g=>{if(gClassOf(g)===cls&&g.subject&&g.subject!=='單元檢測')c.set(g.subject,(c.get(g.subject)||0)+1);});const top=[...c].sort((a,b)=>b[1]-a[1])[0];return top?top[0]:/數學/.test(className(cls))?'數學':'英文';}
function gCellChange(t){const d=t.dataset,sec=d.gsec,sid=d.sid,cls=gClass,subj=gClassSubject(cls);let match,base;
 if(sec==='數學檢測'){match=g=>g.section===sec&&g.studentId===sid&&g.title===d.title&&(g.paper||'')===(d.paper||'')&&g.date===(d.date||gEntryDate)&&gClassOf(g)===cls;base={...mathAssessmentGradeBase(sid,d.title,d.paper||''),date:d.date||gEntryDate};}
 else if(sec==='每週單字'){match=g=>g.section===sec&&g.studentId===sid&&g.date===d.date&&gClassOf(g)===cls;base={section:sec,studentId:sid,classId:cls,date:d.date,subject:subj,title:'每週單字測驗',paper:'',maxScore:'100',passScore:'80'};}
 else if(sec==='檢測'){match=g=>g.section===sec&&g.studentId===sid&&g.title===d.title&&(g.paper||'')===d.paper&&gClassOf(g)===cls;base={section:sec,studentId:sid,classId:cls,date:gEntryDate||today(),subject:subj,title:d.title,paper:d.paper,maxScore:'100',passScore:d.paper==='B'?'60':'80'};}
 else{match=g=>g.section===sec&&g.studentId===sid&&normTitle(g.title)===normTitle(d.title)&&gClassOf(g)===cls;base={section:sec,studentId:sid,classId:cls,date:gEntryDate||today(),subject:'英文',title:d.title,paper:'',maxScore:d.title==='認讀卷'?'50':'100',passScore:d.title==='認讀卷'?'40':'80'};}
 const p=gParse(t.value);if(p===undefined){toast('請輸入 0–1000 的分數、PASS（通過），或「缺」「免」；清空即刪除。');t.focus();return;}
 const ex=gLatest(data.grades.filter(match));
 if(sec==='數學檢測'&&p&&p.score!==''&&Number(p.score)>gMax(ex||base)){toast('分數不可超過設定的滿分 '+gMax(ex||base)+'。');t.focus();return;}
 if(p===null){if(!ex)return;data.grades=data.grades.filter(g=>g!==ex);}else if(ex){if(gCellVal(ex)===t.value.trim())return;Object.assign(ex,p);}else data.grades.push({id:uid(),...base,...p,note:''});
 data.grades.forEach(g=>delete g._n);changed();
 setTimeout(()=>{const a=document.activeElement,ck=a&&a.dataset?a.dataset.ck:null,sl=[...document.querySelectorAll('.tablewrap')].map(x=>x.scrollLeft),y=window.scrollY;render();document.querySelectorAll('.tablewrap').forEach((x,i)=>x.scrollLeft=sl[i]||0);window.scrollTo(0,y);if(ck){const n=document.querySelector('.gcell[data-ck="'+CSS.escape(ck)+'"]');if(n)n.focus();}},0);}
