function presetClasses(){const add=DEFAULT_CLASSES.filter(n=>!data.classes.some(c=>c.name===n));if(!add.length){toast('預設班級都已建立。');return;}add.forEach(n=>data.classes.push({id:uid(),name:n,kind:kindFromName(n),mode:'差異化教學',online:'實體',teacher:'',schedule:'',weekdays:'',gradeRule:true,room:'',meetUrl:'',note:''}));changed();render();toast('已建立：'+add.join('、'));}
function autoMonitors(){if(!filterClass){toast('請先在「班級」篩選選擇要排班的班級。');return;}if(isOnline(filterClass)){toast('線上班級不需要安排值日生。');return;}const month=(filterDate||today()).slice(0,7),list=classStudents(filterClass);if(!list.length){toast('這個班級還沒有學生。');return;}
 const days=monthDays(month).filter(d=>!data.monitors.some(r=>r.classId===filterClass&&r.date===d));if(!days.length){toast(month+' 每個上課日都已安排值日生。');return;}
 if(!confirm('依學生編號，為「'+className(filterClass)+'」自動安排 '+month+' 尚未排定的 '+days.length+' 天值日生？'))return;
 const prev=data.monitors.filter(r=>r.classId===filterClass&&r.date<days[0]).sort((a,b)=>b.date.localeCompare(a.date));const ptr={};let n=0;
 days.forEach(d=>{const pool=list.filter(s=>allowedOn(s,d,filterClass));if(!pool.length)return;const k=pool.map(s=>s.id).join();if(ptr[k]==null){const last=prev.find(r=>pool.some(s=>s.id===r.studentId));ptr[k]=last?pool.findIndex(s=>s.id===last.studentId)+1:0;}
  data.monitors.push({id:uid(),date:d,classId:filterClass,studentId:pool[ptr[k]%pool.length].id,job:'值日生',done:false,note:''});ptr[k]++;n++;});
 changed();render();toast('已安排 '+n+' 天值日生。');}
function copyCleaning(){if(!filterClass){toast('請先在「班級」篩選選擇班級。');return;}if(isOnline(filterClass)){toast('線上班級不需要安排清潔工作。');return;}const base=filterDate||today(),monday=addDays(base,-((weekday(base)+6)%7)),from=addDays(monday,-7);
 const src=data.cleaning.filter(r=>r.classId===filterClass&&r.date>=from&&r.date<monday);if(!src.length){toast('上一週（'+from+' 起）沒有清潔分配可複製。');return;}
 let n=0;src.forEach(r=>{const date=addDays(r.date,7);if(data.cleaning.some(x=>x.classId===r.classId&&x.date===date&&x.area===r.area&&x.studentId===r.studentId))return;data.cleaning.push({...r,id:uid(),date,done:false});n++;});
 changed();render();toast(n?'已複製 '+n+' 筆清潔工作到 '+monday+' 這一週。':'這一週已有相同分配。');}
