 live(st.gradeExams).forEach(g=>(Array.isArray(g.scores)?g.scores:[]).forEach(x=>{if(!x||!x.student)return;d.grades.push({id:uid(),studentId:x.student,section:({daily:'每週單字',unit:'檢測',vocab:'單字檢定'})[g.testType]||'',classId:g.classId||'',date:g.date||'',subject:clean(g.subject)||'英文',title:clean(g.title)||'檢測',exempt:false,absent:!!x.absent||clean(x.note)==='缺考',score:x.score==null?'':String(x.score),maxScore:g.maxScore==null?'':String(g.maxScore),passScore:g.passScore==null?'':String(g.passScore),note:clean(x.note)==='缺考'?'':clean(x.note)});}));
