 live(st.quickLinks).forEach(l=>{if(clean(l.url))d.links.push({id:okId(l.id),title:clean(l.title)||clean(l.url),url:clean(l.url),category:clean(l.category),note:''});});
 live(st.teachers).forEach(t=>d.teachers.push({id:okId(t.id),name:clean(t.name),subject:'',schedule:'',room:'',contact:'',note:t.approved===false?'尚未核准':''}));
 live(st.specialPrograms).forEach(p=>d.tasks.push({id:okId(p.id),studentId:'',title:clean(p.title)||'特殊任務',date:p.start||'',done:!!p.archived,note:[join(clean(p.kind),p.start&&'期間 '+p.start+'～'+(p.end||'')),(p.students||[]).length?'學生：'+p.students.map(sName).filter(Boolean).join('、'):'',clean(p.notes),...(Array.isArray(p.tasks)?p.tasks:[]).map(t=>(t.done?'✓ ':'○ ')+clean(t.text).slice(0,60))].filter(Boolean).join('\n')}));
