const LIB_SITE='https://sindy1687.github.io/boyolibray2026.09.08/';
const LIB_API_DEFAULT='https://script.google.com/macros/s/AKfycbxYZodHltoNvStyYHg3iHwflZ2W6g3vPNKftIOo3e8A22-jNL_-j_GmBbxzZwLt9Ot_/exec';
const LIB_STORE='sindy-library-books-v1',BOOK_GENRE={A:'繪本',B:'橋樑書',C:'文字書',D:'雜誌'};
let library={books:[],fetchedAt:0,loading:null,error:''};
try{const c=JSON.parse(localStorage.getItem(LIB_STORE)||'null');if(c&&Array.isArray(c.books))library.books=c.books.filter(b=>b&&typeof b.id==='string'&&typeof b.title==='string'),library.fetchedAt=+c.fetchedAt||0;}catch{}
const libApi=()=>(data&&data.meta&&data.meta.libraryApi)||LIB_API_DEFAULT;
async function libCall(action){const ctl=new AbortController(),t=setTimeout(()=>ctl.abort(),45000);
 try{const r=await fetch(libApi()+'?payload='+encodeURIComponent(JSON.stringify({action})),{cache:'no-store',signal:ctl.signal});if(!r.ok)throw Error('HTTP '+r.status);let j;try{j=JSON.parse(await r.text());}catch{throw Error('書庫回傳的不是資料');}
  if(!j||!j.ok||!j.data||!Array.isArray(j.data.books))throw Error(j&&j.error||'書庫資料格式不正確');return j.data.books;}finally{clearTimeout(t);}}
function libNormalize(raw){const m=new Map();(raw||[]).forEach(b=>{if(!b||typeof b!=='object')return;const title=String(b.title||b.name||'').trim().slice(0,300);[b.id,...(Array.isArray(b.bookIds)?b.bookIds:[])].forEach(x=>{const id=String(x||'').trim().toUpperCase();if(/^[ABCD]\d+$/.test(id)&&title&&!m.has(id))m.set(id,{id,title,author:String(b.author||'').trim().slice(0,120),series:String(b.series||'').trim().slice(0,120)});});});
 return [...m.values()].sort((a,b)=>a.id.localeCompare(b.id,'en',{numeric:true}));}
function loadLibrary(force){if(library.loading)return library.loading;if(!force&&library.books.length&&Date.now()-library.fetchedAt<12*3600e3)return Promise.resolve(library.books);
 library.error='';library.loading=libCall('pullBookIds').then(raw=>{const b=libNormalize(raw);return b.length?b:libCall('pull').then(libNormalize);}).catch(()=>libCall('pull').then(libNormalize))
  .then(books=>{if(!books.length)throw Error('書庫沒有可用的書碼');library.books=books;library.fetchedAt=Date.now();try{localStorage.setItem(LIB_STORE,JSON.stringify({books,fetchedAt:library.fetchedAt}));}catch{}return books;})
  .catch(e=>{library.error=e&&e.name==='AbortError'?'連線逾時':(e&&e.message)||String(e);return library.books;})
  .finally(()=>{library.loading=null;updateLibStatus();});
 updateLibStatus();return library.loading;}
function libStatusHtml(){const n=library.books.length,when=library.fetchedAt?new Date(library.fetchedAt).toLocaleString('zh-TW',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';
 const txt=library.loading?'正在讀取圖書館書庫…':library.error?'書庫讀取失敗（'+esc(library.error)+'）'+(n?'，暫用上次的 '+n+' 本':'，仍可直接輸入書名'):n?'圖書館書庫 '+n+' 本 · 更新於 '+esc(when)+'；輸入書碼或書名即可搜尋':'尚未載入圖書館書庫';
 return '<span>📚 '+txt+'</span> <button type="button" class="iconbtn" data-action="libRefresh" '+(library.loading?'disabled':'')+'>重新整理書庫</button> <a href="'+LIB_SITE+'" target="_blank" rel="noopener noreferrer">開啟圖書館 ↗</a>';}
function updateLibStatus(){document.querySelectorAll('.libstatus').forEach(el=>el.innerHTML=libStatusHtml());}
function libSearch(q){q=String(q||'').trim();if(!q||!library.books.length)return [];const up=q.toUpperCase().replace(/\s+/g,''),nt=normTitle(q);
 const score=b=>b.id===up?0:b.id.startsWith(up)?1:normTitle(b.title).startsWith(nt)?2:normTitle(b.title).includes(nt)?3:normTitle(b.series).includes(nt)||normTitle(b.author).includes(nt)?4:9;
 return library.books.map(b=>[score(b),b]).filter(x=>x[0]<9).sort((a,b)=>a[0]-b[0]||a[1].id.localeCompare(b[1].id,'en',{numeric:true})).slice(0,8).map(x=>x[1]);}
