 const set={gEntryDate:v=>gEntryDate=v||today(),gClass:v=>gClass=v,gSubject:v=>gSubject=v,gMonth:v=>gMonth=v,classFilter:v=>filterClass=v,dateFilter:v=>filterDate=v,jClass:v=>jClass=v,jDate:v=>jDate=v||today(),jMonth:v=>jMonth=v,aClass:v=>aClass=v,aMonth:v=>aMonth=v||today().slice(0,7),rClass:v=>rClass=v,rFrom:v=>rFrom=v,rTo:v=>rTo=v,mClass:v=>mClass=v,mFrom:v=>mFrom=v,mTo:v=>mTo=v};
