$('cancel').onclick=()=>$('editor').close();$('menu').onclick=()=>$('sidebar').classList.add('open');$('closeMenu').onclick=()=>$('sidebar').classList.remove('open');document.addEventListener('click',e=>{const s=$('sidebar');if(s.classList.contains('open')&&e.target.isConnected&&!e.target.closest('#sidebar,#menu'))s.classList.remove('open');});
$('importFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8e6)throw Error('備份檔案太大。');const parsed=JSON.parse(await file.text());const legacy=isLegacyBackup(parsed);const incoming=legacy?convertLegacy(parsed.state):validateImport(parsed.data&&parsed.schema==null?parsed.data:parsed);
 if(!confirm((legacy?'這是參考網站的備份（'+String(parsed.exported||'').slice(0,10)+'），已轉換為本工作台格式。\n':'')+'將匯入：'+importSummary(incoming)+'\n\n匯入會取代目前資料，系統會先下載一份目前資料。確定繼續？'))return;exportData();data=incoming;jClass='';aClass='';rClass='';mClass='';changed();page='總覽';render();toast('已匯入：'+importSummary(incoming));}catch(err){toast('匯入失敗：'+err.message);}finally{e.target.value='';}};
window.addEventListener('storage',e=>{if(e.key!==STORE||!e.newValue||$('editor').open)return;try{data=validateImport(JSON.parse(e.newValue));render();toast('已同步其他分頁的修改。');}catch{}});
data=loadData();applyAnnualGradePromotion(data);persist();try{const last=localStorage.getItem('sindy-classroom-page');if(last&&(modules[last]||['總覽','學生週誌','閱讀統計','個人閱讀清單','資料匯入匯出'].includes(last)))page=last;}catch{}status(data.students.length?'✓ 已載入本機資料':'歡迎使用');render();
